 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            colored = [(y,x) for y,x in comp if grid[y][x] not in (0,8)]
            if not colored:
                continue
            top, bottom = min(y for y,x in colored), max(y for y,x in colored)
            left, right = min(x for y,x in colored), max(x for y,x in colored)
            mh, mw = bottom-top+1, right-left+1
            pattern = [[grid[top+dy][left+dx] for dx in range(mw)] for dy in range(mh)]
            # Tile the colored seed's full bounding rectangle throughout its zero field.
            for y,x in comp:
                out[y][x] = pattern[(y-top) % mh][(x-left) % mw]
    return out
